<?php
require_once __DIR__ . '/../includes/functions.php'; require_login();
$user=current_user();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$task=['title'=>'','description'=>'','subject_id'=>'','due_date'=>'','priority'=>'medium'];$errors=[];
if($id){$stmt=db()->prepare('SELECT * FROM study_tasks WHERE id=? AND user_id=?');$stmt->execute([$id,$user['id']]);$found=$stmt->fetch();if(!$found){flash('error','Task not found.');redirect('tasks.php');}$task=$found;}
$stmt=db()->prepare('SELECT id,name FROM subjects WHERE user_id=? ORDER BY name');$stmt->execute([$user['id']]);$subjects=$stmt->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$task['title']=trim((string)($_POST['title']??''));$task['description']=trim((string)($_POST['description']??''));$task['subject_id']=(string)($_POST['subject_id']??'');$task['due_date']=(string)($_POST['due_date']??'');$task['priority']=(string)($_POST['priority']??'medium');
 if(mb_strlen($task['title'])<2||mb_strlen($task['title'])>180)$errors[]='Task title must be between 2 and 180 characters.';
 if(mb_strlen($task['description'])>2000)$errors[]='Description must be 2,000 characters or fewer.';
 if(!in_array($task['priority'],['low','medium','high'],true))$errors[]='Choose a valid priority.';
 $subjectId=$task['subject_id']===''?null:(int)$task['subject_id'];
 if($subjectId){$check=db()->prepare('SELECT id FROM subjects WHERE id=? AND user_id=?');$check->execute([$subjectId,$user['id']]);if(!$check->fetch())$errors[]='Choose one of your own subjects.';}
 if($task['due_date']!==''&&!valid_date($task['due_date']))$errors[]='Choose a valid deadline.';
 if(!$errors){$due=$task['due_date']===''?null:$task['due_date'];if($id){$stmt=db()->prepare('UPDATE study_tasks SET subject_id=?,title=?,description=?,due_date=?,priority=? WHERE id=? AND user_id=?');$stmt->execute([$subjectId,$task['title'],$task['description'],$due,$task['priority'],$id,$user['id']]);flash('success','Task updated.');}else{$stmt=db()->prepare("INSERT INTO study_tasks(user_id,subject_id,title,description,due_date,priority,status) VALUES(?,?,?,?,?,?,'pending')");$stmt->execute([$user['id'],$subjectId,$task['title'],$task['description'],$due,$task['priority']]);flash('success','Study task added.');}redirect('tasks.php');}
}
$pageTitle=$id?'Edit task':'Add task';$activePage='tasks';require __DIR__.'/../includes/header.php';
?>
<section class="page-heading"><div><div class="eyebrow">MAKE A PLAN</div><h1><?= $id?'Edit your task':'Add a study task' ?></h1><p>Give your next study session a clear goal.</p></div><a class="btn btn-secondary" href="tasks.php">← Back to tasks</a></section>
<section class="panel form-panel"><?php foreach($errors as $err): ?><div class="toast toast-error" role="alert"><span>!</span><?= e($err) ?></div><?php endforeach; ?><form method="post" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-grid"><div class="form-field full"><label for="title">Task title *</label><input id="title" name="title" maxlength="180" placeholder="e.g. Revise recursion and solve 5 problems" value="<?= e($task['title']) ?>" required></div><div class="form-field full"><label for="description">Notes</label><textarea id="description" name="description" maxlength="2000" placeholder="Add chapters, links, or what you want to accomplish."><?= e($task['description']??'') ?></textarea></div><div class="form-field"><label for="subject_id">Subject</label><select id="subject_id" name="subject_id"><option value="">No subject</option><?php foreach($subjects as $s): ?><option value="<?= (int)$s['id'] ?>" <?= (string)$task['subject_id']===(string)$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select><?php if(!$subjects): ?><span class="form-help">You can <a class="text-link" href="subject_form.php">create a subject</a> first.</span><?php endif; ?></div><div class="form-field"><label for="due_date">Deadline</label><input id="due_date" name="due_date" type="date" value="<?= e((string)($task['due_date']??'')) ?>"></div><div class="form-field"><label for="priority">Priority</label><select id="priority" name="priority"><option value="low" <?= $task['priority']==='low'?'selected':'' ?>>Low — when you can</option><option value="medium" <?= $task['priority']==='medium'?'selected':'' ?>>Medium — important</option><option value="high" <?= $task['priority']==='high'?'selected':'' ?>>High — focus soon</option></select></div></div><div class="form-actions"><button class="btn btn-primary" type="submit"><?= $id?'Save changes':'Add task' ?></button><a class="btn btn-secondary" href="tasks.php">Cancel</a></div></form></section>
<?php require __DIR__.'/../includes/footer.php'; ?>
